package com.automationstudio.engine.karate;
import static org.junit.jupiter.api.Assertions.*;import java.util.*;import org.junit.jupiter.api.Test;
class DockerGatewayCommandTest{
 private static final String ID="b".repeat(32),NETWORK="as-karate-net-"+ID,GATEWAY="as-karate-gateway-"+ID,IMAGE="local/gateway@sha256:"+"a".repeat(64);
 @Test void createsInternalExecutionNetworkAndContainedDualHomedGateway(){assertTrue(DockerGatewayCommand.networkCreate(NETWORK,ID).contains("--internal"));var create=DockerGatewayCommand.create(GATEWAY,IMAGE,UUID.fromString("bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb"),"https://example.com",1000,3,WorkerLimits.defaults(),false);assertPair(create,"--network","bridge");assertTrue(create.contains("--interactive"));assertFalse(create.contains("--pid"));assertPair(create,"--user","10002:10002");assertPair(create,"--cap-drop","ALL");assertPair(create,"--security-opt","no-new-privileges:true");assertPair(create,"--security-opt","seccomp=builtin");assertFalse(create.contains("--publish"));assertFalse(create.stream().anyMatch(v->v.contains("docker.sock")||v.toLowerCase().contains("proxy")));assertEquals("3",create.get(create.size()-2));var connect=DockerGatewayCommand.connect(NETWORK,GATEWAY);assertPair(connect,"--alias",GATEWAY);}
 @Test void rejectsFloatingGatewayImageAndInvalidParallelism(){assertThrows(IllegalArgumentException.class,()->DockerGatewayCommand.create(GATEWAY,"latest",UUID.randomUUID(),"https://example.com",1000,1,WorkerLimits.defaults(),false));assertThrows(IllegalArgumentException.class,()->DockerGatewayCommand.create(GATEWAY,IMAGE,UUID.randomUUID(),"https://example.com",1000,9,WorkerLimits.defaults(),false));}
 private static void assertPair(List<String> c,String k,String v){assertTrue(java.util.stream.IntStream.range(0,c.size()-1).anyMatch(i->c.get(i).equals(k)&&c.get(i+1).equals(v)));}
}
